// Generated by esquadro: do not edit. The list of a resource, with
// TanStack Table and shadcn/ui's Table (its data-table): the API's filters,
// sorting, search and pages, all in the URL, so that it can be shared and
// Back works; records selected to act on several at once; cells changed in
// place; each record's actions in its menu.
import { keepPreviousData, useQuery, useQueryClient } from "@tanstack/react-query"
import {
  columnVisibilityFeature,
  createColumnHelper,
  FlexRender,
  rowSelectionFeature,
  tableFeatures,
  useTable,
  type ColumnVisibilityState,
} from "@tanstack/react-table"
import { Link, useNavigate, useSearch } from "@tanstack/react-router"
import {
  ArrowDown,
  ArrowUp,
  ArrowUpDown,
  ChevronLeft,
  ChevronRight,
  Columns3,
  Eye,
  Inbox,
  MoreHorizontal,
  Pencil,
  Plus,
  Search,
  Trash2,
  X,
} from "lucide-react"
import { useEffect, useMemo, useState } from "react"
import { Button } from "@/components/ui/button"
import { Checkbox } from "@/components/ui/checkbox"
import {
  DropdownMenu,
  DropdownMenuCheckboxItem,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import { Empty, EmptyDescription, EmptyHeader, EmptyMedia, EmptyTitle } from "@/components/ui/empty"
import { Input } from "@/components/ui/input"
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select"
import { Skeleton } from "@/components/ui/skeleton"
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table"
import { api } from "../api.ts"
import { EditableCell } from "./cell.tsx"
import { ask } from "./confirm.tsx"
import { describe } from "./errors.ts"
import { capitalize, format, t } from "./i18n.ts"
import type { Rec } from "./meta.ts"
import { PageHeader } from "./page.tsx"
import { columnField, columnOptions } from "./resource.ts"
import type { Action, Resource } from "./resource.ts"
import { FieldValue } from "./show.tsx"
import { toast } from "./toast.tsx"

const ALL = "__all"
const PER_PAGE = 25

const features = tableFeatures({ columnVisibilityFeature, rowSelectionFeature })
const helper = createColumnHelper<typeof features, Rec>()

/** The list's state, in the URL. */
export interface ListSearch {
  page?: number
  cursor?: string
  q?: string
  sort?: string
  [filter: string]: string | number | undefined
}

/** Validates the list's URL: for the route's validateSearch. */
export function listSearch(search: Record<string, unknown>): ListSearch {
  const out: ListSearch = {}
  for (const [k, v] of Object.entries(search)) {
    if (k === "page") out.page = Number(v) > 0 ? Number(v) : undefined
    else if (typeof v === "string" || typeof v === "number") out[k] = v
  }
  return out
}

/** Runs an action on each record, in turn; how many went through and failed. */
async function each(records: Rec[], run: (r: Rec) => Promise<unknown> | unknown) {
  let done = 0
  let failed = 0
  let error: unknown
  for (const r of records) {
    try {
      await run(r)
      done++
    } catch (e) {
      failed++
      error = e
    }
  }
  return { done, failed, error }
}

export function ResourceList({ resource, description }: { resource: Resource; description?: string }) {
  const { meta } = resource
  const search = useSearch({ strict: false }) as ListSearch
  const navigate = useNavigate()
  const queryClient = useQueryClient()
  const paged = meta.pagination.includes("page")
  const query: Record<string, unknown> = { ...search }
  if (paged) {
    query.page = search.page ?? 1
    query.per_page = PER_PAGE
  } else {
    query.limit = PER_PAGE
  }
  const list = useQuery({
    queryKey: [meta.name, "list", query],
    queryFn: () => meta.api(api as never).list(query),
    placeholderData: keepPreviousData,
  })
  const set = (changes: Partial<ListSearch>) =>
    navigate({ to: ".", search: (s: Record<string, unknown>) => ({ ...s, ...changes }) as never })

  const page = list.data
  const items = useMemo(() => page?.items ?? [], [page])
  const actions = resource.actions ?? []
  const bulkActions = actions.filter((a) => a.bulk)
  const canDeleteAny = items.some((r) => (r.can ?? []).includes("delete"))
  const selectable = resource.table.select !== false && (bulkActions.length > 0 || canDeleteAny)

  const [rowSelection, setRowSelection] = useState({})
  const [columnVisibility, setColumnVisibility] = useState<ColumnVisibilityState>(() =>
    Object.fromEntries(resource.table.columns.filter((c) => columnOptions(c).hidden).map((c) => [columnField(c).name, false])),
  )
  // Another page, filter or sorting: nothing selected.
  useEffect(() => setRowSelection({}), [JSON.stringify(search)])

  const remove = (r: Rec) => meta.api(api as never).delete(r.id, { ifMatch: r })
  const runOne = async (a: Action, r: Rec) => {
    if (a.confirm && !(await ask(a.confirm, { destructive: a.destructive }))) return
    try {
      await a.run(r)
      toast(t("done"))
    } catch (e) {
      toast(describe(e), "error")
    }
    queryClient.invalidateQueries({ queryKey: [meta.name] })
  }

  const columns = useMemo(() => {
    const out = []
    if (selectable) {
      out.push(
        helper.display({
          id: "select",
          header: ({ table }) => (
            <Checkbox
              checked={table.getIsAllPageRowsSelected() || (table.getIsSomePageRowsSelected() && "indeterminate")}
              onCheckedChange={(v) => table.toggleAllPageRowsSelected(!!v)}
              aria-label={t("selectAll")}
            />
          ),
          cell: ({ row }) => (
            <Checkbox
              checked={row.getIsSelected()}
              onCheckedChange={(v) => row.toggleSelected(!!v)}
              onClick={(e) => e.stopPropagation()}
              aria-label={t("selectRow")}
            />
          ),
          enableHiding: false,
        }),
      )
    }
    for (const c of resource.table.columns) {
      const f = columnField(c)
      const o = columnOptions(c)
      const label = o.label ?? f.label
      out.push(
        helper.accessor((r: Rec) => r[f.name], {
          id: f.name,
          meta: { label },
          header: () => {
            if (!meta.sorts.includes(f.name)) return label
            const Icon = search.sort === f.name ? ArrowUp : search.sort === `-${f.name}` ? ArrowDown : ArrowUpDown
            return (
              <Button
                variant="ghost"
                size="sm"
                className="-ml-3 h-8"
                onClick={() => set({ sort: search.sort === f.name ? `-${f.name}` : f.name, cursor: undefined })}
              >
                {label}
                <Icon className="text-muted-foreground" />
              </Button>
            )
          },
          cell: ({ row }) =>
            o.cell ? o.cell(row.original) : o.editable ? (
              <EditableCell meta={meta} field={f} record={row.original} />
            ) : (
              <FieldValue field={f} record={row.original} />
            ),
        }),
      )
    }
    out.push(
      helper.display({
        id: "actions",
        header: () => <span className="sr-only">{t("actions")}</span>,
        cell: ({ row }) => {
          const r = row.original
          const can = r.can ?? []
          const own = actions.filter((a) => !a.when || a.when(r))
          return (
            <div className="flex justify-end" onClick={(e) => e.stopPropagation()}>
              <DropdownMenu>
                <DropdownMenuTrigger asChild>
                  <Button variant="ghost" size="icon-sm" className="data-[state=open]:bg-muted" aria-label={t("openMenu")}>
                    <MoreHorizontal />
                  </Button>
                </DropdownMenuTrigger>
                <DropdownMenuContent align="end" className="min-w-44">
                  <DropdownMenuItem asChild>
                    <Link to={`/${meta.name}/${r.id}` as never}>
                      <Eye /> {t("view")}
                    </Link>
                  </DropdownMenuItem>
                  {can.includes("update") && (
                    <DropdownMenuItem asChild>
                      <Link to={`/${meta.name}/${r.id}/edit` as never}>
                        <Pencil /> {t("edit")}
                      </Link>
                    </DropdownMenuItem>
                  )}
                  {own.length > 0 && <DropdownMenuSeparator />}
                  {own.map((a) => (
                    <DropdownMenuItem key={a.label} variant={a.destructive ? "destructive" : "default"} onClick={() => runOne(a, r)}>
                      {a.icon && <a.icon />} {a.label}
                    </DropdownMenuItem>
                  ))}
                  {can.includes("delete") && (
                    <>
                      <DropdownMenuSeparator />
                      <DropdownMenuItem
                        variant="destructive"
                        onClick={async () => {
                          if (!(await ask(t("confirmDelete"), { destructive: true }))) return
                          try {
                            await remove(r)
                            toast(t("deleted"))
                          } catch (e) {
                            toast(describe(e), "error")
                          }
                          queryClient.invalidateQueries({ queryKey: [meta.name] })
                        }}
                      >
                        <Trash2 /> {t("delete")}
                      </DropdownMenuItem>
                    </>
                  )}
                </DropdownMenuContent>
              </DropdownMenu>
            </div>
          )
        },
        enableHiding: false,
      }),
    )
    return helper.columns(out)
  }, [resource, selectable, search.sort, meta, actions])

  const table = useTable({
    features,
    data: items,
    columns,
    state: { rowSelection, columnVisibility },
    getRowId: (r) => r.id,
    enableRowSelection: true,
    onRowSelectionChange: setRowSelection,
    onColumnVisibilityChange: setColumnVisibility,
  })

  const selected = items.filter((r) => (rowSelection as Record<string, boolean>)[r.id])
  const runBulk = async (label: string, records: Rec[], run: (r: Rec) => Promise<unknown> | unknown, question?: string, destructive?: boolean) => {
    if (question && !(await ask(question, { destructive }))) return
    const { done, failed, error } = await each(records, run)
    if (failed === 0) toast(t("bulkDone", { done, label }))
    else toast(t("bulkFailed", { done, failed, error: describe(error) }), "error")
    setRowSelection({})
    queryClient.invalidateQueries({ queryKey: [meta.name] })
  }

  const searchable = resource.table.search !== false && meta.sorts.includes("relevance")
  const filters = resource.table.filters ?? []
  const current = search.page ?? 1
  const hideable = table.getAllColumns().filter((c) => c.getCanHide())
  const width = table.getVisibleLeafColumns().length
  return (
    <div className="flex flex-col gap-4">
      <PageHeader
        title={meta.label}
        description={description}
        actions={
          page?.can.includes("create") && (
            <Button asChild>
              <Link to={`/${meta.name}/new` as never}>
                <Plus /> {t("new")}
              </Link>
            </Button>
          )
        }
      />
      <div className="flex flex-wrap items-center gap-2">
        {searchable && (
          <div className="relative w-full sm:w-72">
            <Search className="pointer-events-none absolute top-1/2 left-2.5 size-4 -translate-y-1/2 text-muted-foreground" />
            <Input
              className="pl-8"
              placeholder={t("search")}
              defaultValue={search.q ?? ""}
              onKeyDown={(e) => {
                if (e.key === "Enter") set({ q: e.currentTarget.value || undefined, page: undefined, cursor: undefined })
              }}
            />
          </div>
        )}
        {filters.map((f) => (
          <Select
            key={f.name}
            value={String(search[f.name] ?? ALL)}
            onValueChange={(v) => set({ [f.name]: v === ALL ? undefined : v, page: undefined, cursor: undefined })}
          >
            <SelectTrigger className="w-auto min-w-40">
              <span className="text-muted-foreground">{f.label}:</span>
              <SelectValue />
            </SelectTrigger>
            <SelectContent position="popper">
              <SelectItem value={ALL}>{capitalize(t("all"))}</SelectItem>
              {(f.values ?? ["true", "false"]).map((v) => (
                <SelectItem key={v} value={v}>
                  {capitalize(f.kind === "bool" ? format(f, v === "true") : format(f, v))}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        ))}
        {hideable.length > 1 && (
          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <Button variant="outline" className="ml-auto">
                <Columns3 /> {t("columns")}
              </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent align="end" className="w-48">
              <DropdownMenuLabel className="text-xs font-normal text-muted-foreground">{t("columns")}</DropdownMenuLabel>
              {hideable.map((c) => (
                <DropdownMenuCheckboxItem
                  key={c.id}
                  checked={c.getIsVisible()}
                  onCheckedChange={(v) => c.toggleVisibility(!!v)}
                  onSelect={(e) => e.preventDefault()}
                >
                  {(c.columnDef.meta as { label?: string } | undefined)?.label ?? c.id}
                </DropdownMenuCheckboxItem>
              ))}
            </DropdownMenuContent>
          </DropdownMenu>
        )}
      </div>
      {selected.length > 0 && (
        <div className="flex flex-wrap items-center gap-2 rounded-lg border bg-muted/50 px-3 py-2 text-sm animate-in fade-in-0 slide-in-from-top-1">
          <span className="font-medium">{t("selected", { count: selected.length })}</span>
          <Button variant="ghost" size="sm" onClick={() => setRowSelection({})}>
            <X /> {t("clearSelection")}
          </Button>
          <div className="ml-auto flex flex-wrap gap-2">
            {bulkActions.map((a) => {
              const records = selected.filter((r) => !a.when || a.when(r))
              return (
                <Button
                  key={a.label}
                  size="sm"
                  variant={a.destructive ? "destructive" : "outline"}
                  disabled={records.length === 0}
                  onClick={() => runBulk(a.label, records, a.run, a.confirm, a.destructive)}
                >
                  {a.icon && <a.icon />} {a.label}
                </Button>
              )
            })}
            {selected.some((r) => (r.can ?? []).includes("delete")) && (
              <Button
                size="sm"
                variant="destructive"
                onClick={() => {
                  const records = selected.filter((r) => (r.can ?? []).includes("delete"))
                  runBulk(t("delete"), records, remove, t("confirmDeleteMany", { count: records.length }), true)
                }}
              >
                <Trash2 /> {t("delete")}
              </Button>
            )}
          </div>
        </div>
      )}
      <div className="overflow-hidden rounded-lg border">
        <Table>
          <TableHeader className="bg-muted/50">
            {table.getHeaderGroups().map((group) => (
              <TableRow key={group.id}>
                {group.headers.map((header) => (
                  <TableHead key={header.id} className={header.column.id === "select" ? "w-10" : header.column.id === "actions" ? "w-12" : undefined}>
                    {header.isPlaceholder ? null : <FlexRender header={header} />}
                  </TableHead>
                ))}
              </TableRow>
            ))}
          </TableHeader>
          <TableBody>
            {list.isPending &&
              Array.from({ length: 5 }, (_, i) => (
                <TableRow key={i}>
                  {Array.from({ length: width }, (_, j) => (
                    <TableCell key={j}>
                      <Skeleton className="h-5 w-full max-w-40" />
                    </TableCell>
                  ))}
                </TableRow>
              ))}
            {table.getRowModel().rows.map((row) => (
              <TableRow
                key={row.id}
                data-state={row.getIsSelected() ? "selected" : undefined}
                className="cursor-pointer"
                onClick={() => navigate({ to: `/${meta.name}/${row.original.id}` as never })}
              >
                {row.getVisibleCells().map((cell) => (
                  <TableCell key={cell.id}>
                    <FlexRender cell={cell} />
                  </TableCell>
                ))}
              </TableRow>
            ))}
          </TableBody>
        </Table>
        {page?.items.length === 0 && (
          <Empty className="border-t">
            <EmptyHeader>
              <EmptyMedia variant="icon">
                <Inbox />
              </EmptyMedia>
              <EmptyTitle>{t("empty")}</EmptyTitle>
              <EmptyDescription>{t("emptyHint")}</EmptyDescription>
            </EmptyHeader>
          </Empty>
        )}
      </div>
      {list.isError && <p className="text-sm text-destructive">{t("somethingWrong")}</p>}
      {paged && page?.total_pages !== undefined && page.total_pages > 1 && (
        <div className="flex items-center justify-end gap-2 text-sm">
          <span className="mr-2 text-muted-foreground">{t("pageOf", { page: current, pages: page.total_pages })}</span>
          <Button variant="outline" size="sm" disabled={current <= 1} onClick={() => set({ page: current - 1 })}>
            <ChevronLeft /> {t("previous")}
          </Button>
          <Button variant="outline" size="sm" disabled={current >= page.total_pages} onClick={() => set({ page: current + 1 })}>
            {t("next")} <ChevronRight />
          </Button>
        </div>
      )}
      {!paged && (search.cursor || page?.next) && (
        <div className="flex items-center justify-end gap-2">
          <Button variant="outline" size="sm" disabled={!search.cursor} onClick={() => history.back()}>
            <ChevronLeft /> {t("previous")}
          </Button>
          <Button variant="outline" size="sm" disabled={!page?.next} onClick={() => set({ cursor: page?.next })}>
            {t("next")} <ChevronRight />
          </Button>
        </div>
      )}
    </div>
  )
}
